const res = $input.first().json;
const body = res.body || res;
if (!Array.isArray(body.projects)) {
  throw new Error('No projects array in response: ' + JSON.stringify(body).slice(0, 300));
}
const total = res.headers ? res.headers['x-pagination-total-count'] : null;
return body.projects.map(p => ({
  json: {
    project_id: p.project_id,
    name: p.name,
    total_projects_header: total,
    fetched_count: body.projects.length
  }
}));

const projItems = $('Expand Projects').all();
const nameById = {};
for (const it of projItems) nameById[it.json.project_id] = it.json.name;

const rows = [];
for (const it of $input.all()) {
  const j = it.json;
  const pid = j.project_id;
  const pname = nameById[pid] || pid;
  if (!Array.isArray(j.languages)) {
    rows.push({ project: pname, project_id: pid, error: JSON.stringify(j).slice(0, 200) });
    continue;
  }
  for (const L of j.languages) {
    rows.push({
      project: pname,
      project_id: pid,
      lang_iso: L.lang_iso,
      lang_id: L.lang_id,
      lang_name: L.lang_name
    });
  }
}

const byIso = {};
const byId = {};
const perProject = {};
for (const r of rows) {
  if (!r.lang_iso) continue;
  byIso[r.lang_iso] = byIso[r.lang_iso] || { ids: {}, names: {}, projects: [] };
  byIso[r.lang_iso].ids[r.lang_id] = byIso[r.lang_iso].ids[r.lang_id] || [];
  byIso[r.lang_iso].ids[r.lang_id].push(r.project);
  byIso[r.lang_iso].names[r.lang_name] = true;
  byIso[r.lang_iso].projects.push(r.project);
  byId[r.lang_id] = byId[r.lang_id] || {};
  byId[r.lang_id][r.lang_iso] = true;
  perProject[r.project] = perProject[r.project] || [];
  perProject[r.project].push(r.lang_iso + ':' + r.lang_id);
}

const isoSummary = Object.keys(byIso).sort().map(iso => ({
  iso,
  names: Object.keys(byIso[iso].names),
  project_count: byIso[iso].projects.length,
  ids: Object.keys(byIso[iso].ids).map(id => ({ id: Number(id), n: byIso[iso].ids[id].length, projects: byIso[iso].ids[id] })),
  id_conflict: Object.keys(byIso[iso].ids).length > 1
}));

const idSummary = Object.keys(byId).map(id => ({ id: Number(id), isos: Object.keys(byId[id]) }))
  .filter(x => x.isos.length > 1);

const projectSummary = Object.keys(perProject).sort().map(p => ({
  project: p,
  count: perProject[p].length,
  codes: perProject[p].sort().join(' ')
}));

return [{ json: {
  total_projects_header: projItems.length ? projItems[0].json.total_projects_header : null,
  projects_fetched: projItems.length,
  total_language_rows: rows.length,
  errors: rows.filter(r => r.error),
  iso_summary: isoSummary,
  shared_ids: idSummary,
  per_project: projectSummary
} }];
